#!/usr/bin/env python3
import csv
import json
from collections import defaultdict
from pathlib import Path

ROOT = Path('/root')


def load_json_catalog(path):
    data = json.load(open(path, newline=''))
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        if isinstance(data.get('programs'), list):
            return data['programs']
        for value in data.values():
            if isinstance(value, list):
                programs = []
                for item in value:
                    if isinstance(item, dict) and isinstance(item.get('programs'), list):
                        programs.extend(item['programs'])
                    elif isinstance(item, dict):
                        programs.append(item)
                if programs:
                    return programs
    raise ValueError('Could not find catalog program array')


def load_csv(path):
    with open(path, newline='') as f:
        return list(csv.DictReader(f))


def money(value):
    return round(float(value), 2)


catalog = load_json_catalog(ROOT / 'program_catalog.json')
cooler_rows = load_csv(ROOT / 'cooler_cost.csv')
payment_rows = load_csv(ROOT / 'contract_payment.csv')
override_rows = load_csv(ROOT / 'site_overrides.csv')

programs = [p for p in catalog if p.get('review_flag') == 'review']
programs_by_code = {p['program_code']: p for p in programs}

label_to_code = {}
for p in programs:
    labels = [p.get('program_name')]
    known_labels = p.get('known_labels') or []
    if isinstance(known_labels, list):
        labels.extend(known_labels)
    else:
        labels.append(known_labels)
    for label in labels:
        if label:
            label_to_code[str(label)] = p['program_code']

payments = {}
payment_matches = defaultdict(list)
for row in payment_rows:
    label = row.get('program_label')
    code = label_to_code.get(label)
    if not code:
        continue
    payment = float(row['payment_per_dispatch_per_site_usd'])
    payment_matches[code].append(row)
    payments[code] = payment

multiple_payment_matches = {
    code: rows for code, rows in payment_matches.items() if len(rows) > 1
}
if multiple_payment_matches:
    details = ', '.join(f"{code}: {len(rows)}" for code, rows in multiple_payment_matches.items())
    raise ValueError(f'Multiple payment rows matched the same in-scope program: {details}')

missing_payments = sorted(set(programs_by_code) - set(payments))
if missing_payments:
    raise ValueError(f'Missing payment rows for in-scope programs: {missing_payments}')

approved_overrides = {}
for row in override_rows:
    if row.get('approval_state') != 'approved':
        continue
    code = row.get('program_code')
    if code not in programs_by_code:
        continue
    version = int(row['version_no'])
    if code not in approved_overrides or version > int(approved_overrides[code]['version_no']):
        approved_overrides[code] = row

cooler_costs = {row['cooler_type']: float(row['cooler_cost_usd']) for row in cooler_rows}

program_outputs = []
models = {
    '10_day': {'days_per_dispatch': 10, 'dispatches_per_year': 36},
    '20_day': {'days_per_dispatch': 20, 'dispatches_per_year': 18},
}

for p in sorted(programs, key=lambda item: str(item['program_code'])):
    code = p['program_code']
    override = approved_overrides.get(code)
    active_sites = int(override['active_sites']) if override else int(p['default_active_sites'])
    cooler_type = p['cooler_type']
    cooler_cost = cooler_costs[cooler_type]
    payment = payments[code]
    acquisition = float(p['acquisition_cost_per_1000_units_usd'])
    units_per_day = float(p['units_per_day'])

    out = {
        'program_code': code,
        'program_name': p.get('program_name'),
        'active_sites': active_sites,
        'active_sites_source': 'approved_override_highest_version' if override else 'catalog_default_active_sites',
        'cooler_type': cooler_type,
        'cooler_cost_usd': money(cooler_cost),
        'payment_per_dispatch_per_site_usd': money(payment),
    }

    margins = {}
    for suffix, model in models.items():
        days = model['days_per_dispatch']
        dispatches = model['dispatches_per_year']
        annual_drug_cost = acquisition * active_sites * units_per_day * days * dispatches / 1000
        annual_cooler_cost = cooler_cost * active_sites * dispatches
        annual_revenue = payment * active_sites * dispatches
        annual_margin = annual_revenue - annual_drug_cost - annual_cooler_cost
        out[f'annual_drug_cost_{suffix}_usd'] = money(annual_drug_cost)
        out[f'annual_cooler_cost_{suffix}_usd'] = money(annual_cooler_cost)
        out[f'annual_revenue_{suffix}_usd'] = money(annual_revenue)
        out[f'annual_margin_{suffix}_usd'] = money(annual_margin)
        margins[suffix] = annual_margin

    out['annual_margin_difference_20_minus_10_usd'] = money(margins['20_day'] - margins['10_day'])
    program_outputs.append(out)

total_10 = money(sum(p['annual_margin_10_day_usd'] for p in program_outputs))
total_20 = money(sum(p['annual_margin_20_day_usd'] for p in program_outputs))
total_diff = money(sum(p['annual_margin_difference_20_minus_10_usd'] for p in program_outputs))
abs_diff = money(abs(total_diff))
decision = 'move_to_20_day' if abs_diff < 10000 else 'keep_10_day'

analysis = {
    'programs': program_outputs,
    'totals': {
        'total_annual_margin_10_day_usd': total_10,
        'total_annual_margin_20_day_usd': total_20,
        'total_annual_margin_difference_20_minus_10_usd': total_diff,
        'absolute_total_margin_difference_usd': abs_diff,
    },
    'recommendation': {
        'decision': decision,
        'justification': (
            f"The absolute total annual margin difference is ${abs_diff:,.2f}, "
            f"compared with the $10,000.00 threshold, so the recommendation is {decision}."
        ),
    },
    'assumptions': {
        'in_scope_filter': 'review_flag must equal exactly review',
        'contract_payment_match': 'program_label is matched exactly to program_name or an entry in known_labels for in-scope programs',
        'active_sites_resolution': 'use the approved site override row with the highest version_no; otherwise use default_active_sites',
        'cooler_cost_formula': 'annual_cooler_cost = cooler_cost_usd * active_sites * dispatches_per_year',
        'currency_rounding': 'round(value, 2)',
        'ten_day_model': {'days_per_dispatch': 10, 'dispatches_per_year': 36},
        'twenty_day_model': {'days_per_dispatch': 20, 'dispatches_per_year': 18},
    },
}

with open(ROOT / 'oncocooler_analysis.json', 'w', newline='') as f:
    json.dump(analysis, f, indent=2)
    f.write('\n')

summary_lines = [
    '# OncoCooler Margin Summary',
    f"Total 10-day margin in USD: ${total_10:,.2f}",
    f"Total 20-day margin in USD: ${total_20:,.2f}",
    f"Absolute difference in USD: ${abs_diff:,.2f}",
    f"Decision: {decision}",
    'Cooler cost interpretation used: cooler_cost_usd * active_sites * dispatches_per_year.',
]
with open(ROOT / 'oncocooler_summary.md', 'w', newline='') as f:
    f.write('\n'.join(summary_lines) + '\n')

print(json.dumps(analysis, indent=2))

