import json
from decimal import Decimal
from pathlib import Path

text = Path('/root/oncocooler_analysis.json').read_text()
data = json.loads(text, parse_float=Decimal, parse_int=Decimal)
program_codes = [p['program_code'] for p in data['programs']]
print('Programs sorted:', program_codes == sorted(program_codes), program_codes)

def currency_key(k):
    return k.endswith('_usd') or k in {'payment_per_dispatch_per_site_usd', 'cooler_cost_usd'}

bad = []
for p in data['programs']:
    for k, v in p.items():
        if currency_key(k) and isinstance(v, Decimal) and abs(v.as_tuple().exponent) > 2:
            bad.append((p['program_code'], k, str(v)))
for section in ('totals',):
    for k, v in data[section].items():
        if currency_key(k) and isinstance(v, Decimal) and abs(v.as_tuple().exponent) > 2:
            bad.append((section, k, str(v)))
print('Currency values at most 2 decimals:', not bad)
if bad:
    print('Bad currency values:', bad)
summary_lines = [line for line in Path('/root/oncocooler_summary.md').read_text().splitlines() if line.strip()]
print('Summary non-empty line count:', len(summary_lines))
print('Summary line count valid:', 4 <= len(summary_lines) <= 8)
summary_decision_lines = [line for line in summary_lines if line.startswith('Decision:')]
summary_decision = summary_decision_lines[0].split(':', 1)[1].strip() if summary_decision_lines else None
print('Summary decision matches JSON:', summary_decision == data['recommendation']['decision'])
print('Cooler cost formula:', data['assumptions']['cooler_cost_formula'])
PY
